"""Thin certified RIND3D adapter. No fields are generated by point queries."""

from collections import Counter
from dataclasses import dataclass
import time
import numpy as np
from .coordinates import xyz64, Window, RESOLUTION
from .data import TeacherScene


class OracleFailure(RuntimeError):
    def __init__(self, message, status="UNRESOLVED"):
        self.status = status
        super().__init__(message)


class QueryBudgetExceeded(OracleFailure):
    def __init__(self, message):
        super().__init__(message, "ABORTED")


@dataclass(frozen=True)
class SourceValidity:
    valid: np.ndarray
    status: tuple[str, ...]
    reasons: tuple[str, ...]


@dataclass(frozen=True)
class VisibilityResult:
    response: np.ndarray  # int8: 1 lit, 0 blocked/solid, -1 invalid source
    solid: np.ndarray
    validity: SourceValidity
    backend: str
    certified: bool
    evaluated_pairs: int
    wall_seconds: float
    cpu_seconds: float


@dataclass(frozen=True)
class WindowResponse:
    response: np.ndarray
    solid: np.ndarray
    backend: str
    certified: bool
    equivalence_certification: bool
    sampled_voxels: int
    wall_seconds: float


class PhysicalOracle:
    """CPU batched arbitrary points; optional certified CUDA window raster.

    Each point call computes a Cartesian source/receiver product in bounded
    chunks. CPU reference uses the original canonical segment service directly.
    CUDA point kernels are not claimed: raster_backend only controls windows.
    """

    def __init__(
        self,
        scene,
        *,
        backend="cpu_native_certified",
        raster_backend="cpu_native_certified",
        max_pairs=1_048_576,
        receiver_batch=4096,
        source_cache=64,
    ):
        if backend not in ("cpu_native_certified", "cpu_reference"):
            raise ValueError(
                "Arbitrary-point backend must be cpu_native_certified or cpu_reference"
            )
        if raster_backend not in ("cpu_native_certified", "cuda_certified", "auto"):
            raise ValueError("Unsupported window backend")
        if max_pairs < 1 or receiver_batch < 1 or source_cache < 1:
            raise ValueError("Positive query/cache limits required")
        try:
            from rind3d.geometry import load_geometry
            from rind3d.rendering.context import GeometryContext
            from rind3d.lite_acceptance import verify_geometry_proof, DRIVER_RADIUS
            from rind3d.rendering.backends import BackendFactory
        except ImportError as exc:
            raise ImportError(
                "Install the Phase 3 physics extra and build canonical native backends; see PHYSICAL_ORACLE.md"
            ) from exc
        if isinstance(scene, TeacherScene):
            bundle = load_geometry(scene.geometry_path)
        elif hasattr(scene, "geometries"):
            bundle = scene
        else:
            raise TypeError(
                "Pass an explicit privileged TeacherScene or canonical synthetic geometry"
            )
        self.context = GeometryContext(bundle, source_cache_size=source_cache)
        verify_geometry_proof(bundle, self.context.geometry_proof())
        if (
            isinstance(scene, TeacherScene)
            and scene.geometry_id != self.context.geometry_id
        ):
            raise ValueError("Teacher scene/geometry identity conflict")
        self.backend = backend
        self.raster_backend = raster_backend
        self.max_pairs = int(max_pairs)
        self.receiver_batch = int(receiver_batch)
        self.clearance = DRIVER_RADIUS
        self.stats = Counter()
        self.closed = False
        self.factory = BackendFactory(geometry_cache=1, cuda_batch=32)

    def source_valid(self, candidate_xyz, *, window=None):
        if self.closed:
            raise RuntimeError("Oracle is closed")
        p = xyz64(candidate_xyz)
        valid = np.zeros(len(p), dtype=bool)
        reasons = []
        for point in p:
            self.stats["source_validity_requests"] += 1
            if np.any(point <= 0) or np.any(point >= 1):
                reasons.append("outside_open_world")
                continue
            if window is not None and window.contains(point)[0]:
                reasons.append("inside_observation")
                continue
            try:
                solid = self.context.native.contains(point[None])
                if np.any(~np.isin(solid, [0, 1])):
                    raise OracleFailure("Unresolved source membership")
                if bool(solid[0]):
                    reasons.append("solid_or_boundary")
                    continue
                clearance = self.context.clearance(point, self.clearance)
                if clearance["status"] == "LE":
                    reasons.append("insufficient_clearance")
                    continue
                if clearance["status"] != "GT":
                    raise OracleFailure("Unresolved source clearance")
            except OracleFailure:
                raise
            except Exception as exc:
                raise OracleFailure(
                    "Source predicate did not certify: " + type(exc).__name__
                ) from exc
            valid[len(reasons)] = True
            reasons.append("free_clearance_certified")
        return SourceValidity(
            valid,
            tuple("CERTIFIED_VALID" if v else "CERTIFIED_INVALID" for v in valid),
            tuple(reasons),
        )

    def evaluate_points(self, candidate_xyz, receiver_xyz, *, window=None):
        sources = xyz64(candidate_xyz)
        receivers = xyz64(receiver_xyz)
        if not len(sources) or not len(receivers):
            raise ValueError("Non-empty source and receiver arrays required")
        if np.any(receivers < 0) or np.any(receivers > 1):
            raise ValueError("Receiver outside closed world [0,1]")
        if len(sources) * len(receivers) > self.max_pairs:
            raise QueryBudgetExceeded(
                "Cartesian source/receiver product exceeds max_pairs"
            )
        start = time.perf_counter()
        cpu = time.process_time()
        validity = self.source_valid(sources, window=window)
        response = np.full((len(sources), len(receivers)), -1, dtype=np.int8)
        solid = np.empty(len(receivers), dtype=bool)
        pairs = 0
        try:
            for offset in range(0, len(receivers), self.receiver_batch):
                q = receivers[offset : offset + self.receiver_batch]
                if self.backend == "cpu_reference":
                    reference = self.context.canonical
                    membership = reference._values(
                        reference.reference.classify_points(q)
                    )
                    if np.any(~np.isin(membership, [0, 1, 2])):
                        raise OracleFailure("Canonical receiver membership unresolved")
                    m = membership != 0  # FREE / INTERIOR / closed BOUNDARY
                    self.stats["canonical_membership_points"] += len(q)
                else:
                    m = self.context.native.contains(q)
                    if np.any(~np.isin(m, [0, 1])):
                        raise OracleFailure("Unresolved receiver membership")
                solid[offset : offset + len(q)] = m
            for i, p in enumerate(sources):
                if not validity.valid[i]:
                    continue
                model = self.context.bind(p)
                self.stats["candidate_evaluations"] += 1
                for offset in range(0, len(receivers), self.receiver_batch):
                    q = receivers[offset : offset + self.receiver_batch]
                    if self.backend == "cpu_reference":
                        reference = self.context.canonical
                        hits = reference._values(
                            reference.reference.segment_intersect(
                                np.repeat(p[None], len(q), axis=0), q
                            )
                        )
                        if np.any(~np.isin(hits, [0, 1])):
                            raise OracleFailure("Canonical segment result unresolved")
                        y = 1 - hits
                    else:
                        y, _, work = model.native.points(q, False)
                        for key, value in work.items():
                            self.stats["native_" + key] += value
                    pairs += len(q)
                    self.stats["source_receiver_pairs"] += len(q)
                    if np.any(~np.isin(y, [0, 1])):
                        raise OracleFailure("Visibility UNKNOWN cannot be a label")
                    response[i, offset : offset + len(q)] = y
            if np.any(response[:, solid] == 1):
                raise OracleFailure("Solid receiver classified lit")
        except OracleFailure:
            raise
        except Exception as exc:
            raise OracleFailure("Physical query failed: " + type(exc).__name__) from exc
        return VisibilityResult(
            response,
            solid,
            validity,
            self.backend,
            True,
            pairs,
            time.perf_counter() - start,
            time.process_time() - cpu,
        )

    def rerender_window(self, candidate_xyz, window):
        p = xyz64(candidate_xyz)
        if len(p) != 1:
            raise ValueError("Window rerender accepts exactly one source")
        if not isinstance(window, Window):
            raise TypeError("Expected Window")
        validity = self.source_valid(p, window=window)
        if not validity.valid[0]:
            raise ValueError("Invalid source: " + validity.reasons[0])
        start = time.perf_counter()
        n = window.side
        try:
            renderer = (
                self.context.bind(p[0])
                if self.raster_backend == "cpu_native_certified"
                else self.factory.source(
                    self.context.bundle, p[0], self.raster_backend, self.context.policy
                )
            )
            try:
                y = np.empty((n,) * 3, dtype=bool)
                m = np.empty_like(y)
                origins = [
                    tuple(np.asarray(window.origin) + [x, j, z])
                    for z in range(0, n, 64)
                    for j in range(0, n, 64)
                    for x in range(0, n, 64)
                ]
                if renderer.backend == "cuda_certified":
                    for pos in range(0, len(origins), 32):
                        chunk = origins[pos : pos + 32]
                        values = renderer.packed_batch(chunk, 64, RESOLUTION)
                        if len(values) != len(chunk):
                            raise OracleFailure("Incomplete certified raster batch")
                        for origin, pair in zip(chunk, values):
                            x, j, z = np.asarray(origin) - window.origin
                            for raw, out in zip(pair, (y, m)):
                                out[z : z + 64, j : j + 64, x : x + 64] = np.unpackbits(
                                    np.frombuffer(raw, dtype=np.uint8),
                                    bitorder="little",
                                ).reshape(64, 64, 64)
                else:
                    # The certified native raster accepts at most 64³ per call.
                    # Tile larger ROIs without changing their unaligned origins.
                    for origin in origins:
                        x, j, z = np.asarray(origin) - window.origin
                        a, b, _ = renderer.render(origin, 64, RESOLUTION, leaf_side=2)
                        y[z : z + 64, j : j + 64, x : x + 64] = a
                        m[z : z + 64, j : j + 64, x : x + 64] = b
                actual = renderer.backend
            finally:
                renderer.close()
        except Exception as exc:
            raise OracleFailure(
                "Window renderer failed: " + type(exc).__name__
            ) from exc
        self.stats["window_rerenders"] += 1
        self.stats["raster_source_voxels"] += n**3
        return WindowResponse(
            y, m, actual, True, False, n**3, time.perf_counter() - start
        )

    def close(self):
        if not self.closed:
            self.factory.close()
            self.closed = True

    def __enter__(self):
        return self

    def __exit__(self, *args):
        self.close()
